use std::{fs,path::Path};use rhwp::{wasm_api::HwpDocument,model::control::Control};
fn main(){let a:Vec<_>=std::env::args().collect();let mut doc=HwpDocument::from_bytes(&fs::read(&a[1]).unwrap()).unwrap();let Control::Table(table)=&doc.document().sections[0].paragraphs[7].controls[0] else{panic!("table")};let count=usize::from(table.col_count);doc.set_table_column_widths_native(0,7,0,vec![12000/count as u32;count]).unwrap();doc.insert_text_native(0,7,0,"가").unwrap();assert_eq!(doc.document().sections[0].paragraphs[7].line_segs.len(),1);fs::write(&a[2],doc.export_hwp_native().unwrap()).unwrap();println!("pageCount={} page_def={:?}",doc.page_count(),doc.document().sections[0].section_def.page_def);let tree=doc.build_page_render_tree(0).unwrap();fs::write(Path::new(&a[2]).with_extension("render-tree.json"),serde_json::to_vec_pretty(&tree).unwrap()).unwrap();}
